// Executes the invocation's actual MCP proxy, without a provider/model/network turn.
import { spawn } from 'node:child_process'
import { createInterface } from 'node:readline'
import { writeFileSync } from 'node:fs'
const args = process.argv.slice(2)
let prompt = ''
for await (const chunk of process.stdin) prompt += chunk
const claude = args.includes('--mcp-config')
let config
if (claude) config = JSON.parse(args[args.indexOf('--mcp-config') + 1]).mcpServers.threadlight
else {
  // Only the constrained invocation generated by codexMemoryArgs, not a general TOML parser.
  const value = args[args.indexOf('-c') + 1]
  config = {
    command: JSON.parse(value.match(/command=("(?:\\.|[^"\\])*")/)[1]),
    args: JSON.parse(value.match(/args=(\[.*\]),env=/)[1]),
    env: { ELECTRON_RUN_AS_NODE: '1' },
  }
}
if (process.env.MEMORY_RELAY_PROOF)
  writeFileSync(process.env.MEMORY_RELAY_PROOF, JSON.stringify({ args, prompt, config }))
const child = spawn(config.command, config.args, {
  env: { ...process.env, ...config.env },
  windowsHide: true,
  stdio: 'pipe',
})
const reply = await new Promise((resolve, reject) => {
  const timer = setTimeout(() => reject(Error('Proxy timed out')), 5000)
  child.once('error', reject)
  createInterface({ input: child.stdout }).once('line', (line) => {
    clearTimeout(timer)
    resolve(JSON.parse(line))
  })
  child.stdin.write(JSON.stringify({ jsonrpc: '2.0', id: 1, method: 'ping' }) + '\n')
})
child.kill()
await new Promise((resolve) => child.once('close', resolve))
if (!reply.result) throw Error('Authenticated MCP call failed')
if (claude) console.log(JSON.stringify({ result: prompt, is_error: false }))
else {
  console.log(JSON.stringify({ type: 'thread.started', thread_id: args.at(-2) }))
  console.log(JSON.stringify({ type: 'turn.started' }))
  console.log(
    JSON.stringify({ type: 'item.completed', item: { type: 'agent_message', text: prompt } }),
  )
  console.log(JSON.stringify({ type: 'turn.completed' }))
}
